            parts = listOf(
                StoryPart(1, "A Covered Piano", listOf(
                    "The school hall contained an upright piano beneath a protective cover. It had not been used during assemblies for years. When the music club planned an afternoon performance, Kola asked whether the piano could be included. The music teacher said it needed inspection before anyone attempted to play it.",
